#!/usr/bin/env python3
"""Genera interfaces paralelas para revisar propuestas VLM I01-I20."""
from __future__ import annotations
import argparse,hashlib,json,shutil
from pathlib import Path
import sys
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from src.tfg_phase0.i20_preparation import canonical_bytes
def load(path):return json.loads(path.read_text(encoding='utf-8'))
def write(path,doc):path.write_bytes(canonical_bytes(doc)+b'\n')
def checksums(root):
 rows=[f"{hashlib.sha256(path.read_bytes()).hexdigest()}  {path.relative_to(root).as_posix()}" for path in sorted(root.rglob('*')) if path.is_file() and path.name!='CHECKSUMS.sha256'];(root/'CHECKSUMS.sha256').write_text('\n'.join(rows)+'\n',encoding='utf-8')
CSS="""*{box-sizing:border-box}body{font:15px system-ui;margin:0;background:#eef0ec;color:#18201c}header{position:sticky;top:0;background:#17372d;color:#fff;padding:12px;z-index:3}main{max-width:1200px;margin:auto;padding:16px}.card{background:#fff;border:1px solid #c8d1ca;border-radius:10px;padding:14px;margin:14px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}img{width:100%;max-height:500px;object-fit:contain;background:#ddd}textarea,input,select,button{font:inherit;width:100%;padding:8px;margin:4px 0 10px}.proposal{background:#edf3ff;border-left:4px solid #4668a8;padding:10px;white-space:pre-wrap}.review{background:#f4f7f3;border-left:4px solid #577b65;padding:10px}.error{display:none;background:#f8d7da;color:#721c24;padding:10px;white-space:pre-wrap}.pending{color:#8a5b00;font-weight:700}.claim{border:1px solid #ccd4ce;padding:8px;margin:8px 0}@media(max-width:760px){.grid{grid-template-columns:1fr}}"""
JS="""const read=input=>new Promise((ok,no)=>{if(!input.files?.[0])return no(Error('Seleccione un JSON'));const r=new FileReader();r.onload=()=>{try{ok(JSON.parse(r.result))}catch(e){no(e)}};r.onerror=no;r.readAsText(input.files[0])});const save=(name,obj)=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)+'\\n'],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};const clone=v=>JSON.parse(JSON.stringify(v));const showError=e=>{const box=document.querySelector('#error');box.style.display='block';box.textContent='Error: '+(e?.message||e)};window.addEventListener('error',e=>showError(e));window.addEventListener('unhandledrejection',e=>showError(e.reason));"""
def scene_html(fixture,plan_id):
 data=json.dumps(fixture,ensure_ascii=False).replace('</','<\\/')
 return f'''<!doctype html><html lang="es"><meta charset="utf-8"><title>I20 asistida · escenas</title><style>{CSS}</style><header><b>I01–I20-assisted-annotation-v1 · escenas</b><div>La propuesta IA no es una decisión humana.</div></header><main><div id="error" class="error"></div><label>Importar propuestas VLM<input id="proposals" type="file" accept="application/json"></label><label>Revisor humano<input id="reviewer"></label><button id="download" disabled>Exportar decisiones humanas</button><div id="cards"></div></main><script type="application/json" id="fixture">{data}</script><script>{JS}const fixture=JSON.parse(document.querySelector('#fixture').textContent),cards=document.querySelector('#cards'),states=new Map();cards.innerHTML=fixture.records.map(r=>`<section class="card" data-id="${{r.pair_id}}"><h2>${{r.left_observation_id}} / ${{r.right_observation_id}}</h2><div class="grid"><img src="${{r.left_reference_path}}"><img src="${{r.right_reference_path}}"></div><div class="proposal">Sin propuesta importada.</div><div class="review"><label>Estado humano<select class="status"><option value="pending">pending</option><option value="reviewed">reviewed</option><option value="corrected">corrected</option><option value="rejected">rejected</option><option value="unresolved">unresolved</option></select></label><label>Misma escena<select data-k="same_scene"><option>yes</option><option>no</option><option>uncertain</option></select></label><label>Objetos distintivos compartidos<select data-k="distinctive_objects_shared"><option>yes</option><option>no</option><option>uncertain</option></select></label><label>Solapamiento FOV<select data-k="field_of_view_overlap"><option>yes</option><option>no</option><option>uncertain</option></select></label><label>Mismo lugar/encuadre alternativo<select data-k="same_place_different_frame"><option>yes</option><option>no</option><option>uncertain</option></select></label><label>Decisión<select data-k="decision"><option>CLEAR</option><option>EXCLUDE</option><option>REVIEW</option></select></label><label>Justificación/razón humana<textarea class="notes"></textarea></label></div></section>`).join('');
document.querySelector('#proposals').onchange=async()=>{{try{{const doc=await read(document.querySelector('#proposals'));if(doc.contract_version!=='i20-assisted-scene-proposals-v1'||doc.plan_id!=='{plan_id}'||doc.records.length!==fixture.records.length)throw Error('Propuestas incompatibles');const expected=fixture.records.map(x=>x.pair_id);if(doc.records.map(x=>x.pair_id).join('|')!==expected.join('|'))throw Error('Pares incompatibles');for(const p of doc.records){{const card=document.querySelector(`[data-id="${{p.pair_id}}"]`),draft=clone(p.ai_draft);states.set(p.pair_id,{{proposal:p,original:clone(draft)}});card.querySelector('.proposal').textContent='PROPUESTA ORIGINAL (solo lectura)\\n'+JSON.stringify(draft,null,2);for(const k of ['same_scene','distinctive_objects_shared','field_of_view_overlap','same_place_different_frame','decision'])card.querySelector(`[data-k="${{k}}"]`).value=draft[k];card.querySelector('.notes').value=draft.justification_es||'';card.querySelector('.status').value='pending'}}document.querySelector('#download').disabled=false}}catch(e){{showError(e)}}}};
document.querySelector('#download').onclick=()=>{{try{{const reviewer=document.querySelector('#reviewer').value.trim();if(!reviewer)throw Error('Falta revisor');const decisions=[];for(const r of fixture.records){{const card=document.querySelector(`[data-id="${{r.pair_id}}"]`),entry=states.get(r.pair_id);if(!entry)throw Error('Falta propuesta '+r.pair_id);const status=card.querySelector('.status').value,revision={{same_scene:card.querySelector('[data-k="same_scene"]').value,distinctive_objects_shared:card.querySelector('[data-k="distinctive_objects_shared"]').value,field_of_view_overlap:card.querySelector('[data-k="field_of_view_overlap"]').value,same_place_different_frame:card.querySelector('[data-k="same_place_different_frame"]').value,decision:card.querySelector('[data-k="decision"]').value,justification_es:card.querySelector('.notes').value,uncertainties:entry.original.uncertainties,human_review_required:true}};if(status==='pending')throw Error('Sigue pending '+r.pair_id);if(status==='reviewed'&&JSON.stringify(revision)!==JSON.stringify(entry.original))throw Error('reviewed contiene cambios '+r.pair_id);if(status==='corrected'&&JSON.stringify(revision)===JSON.stringify(entry.original))throw Error('corrected sin cambios '+r.pair_id);if(['rejected','unresolved'].includes(status)&&!revision.justification_es.trim())throw Error('Falta razón '+r.pair_id);decisions.push({{decision_id:'pending-python-content-id',target_kind:'scene_pair',target_id:r.pair_id,proposal_id:entry.proposal.proposal_id,status,reviewer_pseudonym:reviewer,reviewed_at_utc:new Date().toISOString(),human_revision:status==='corrected'?revision:null,reason_codes:['human_'+status],notes_es:revision.justification_es||null}})}}save('i20-assisted-scene-human-decisions.draft.json',{{schema_version:'1.0',contract_version:'i20-assisted-human-decisions-v1',artifact_id:'pending-python-content-id',plan_id:'{plan_id}',decisions}})}}catch(e){{showError(e)}}}};document.documentElement.dataset.ready='true';</script></html>'''
def annotation_html(fixture,plan_id):
 data=json.dumps(fixture,ensure_ascii=False).replace('</','<\\/')
 return f'''<!doctype html><html lang="es"><meta charset="utf-8"><title>I20 asistida · anotación</title><style>{CSS}</style><header><b>I01–I20-assisted-annotation-v1 · borradores</b><div>Revise cada propuesta: no cambiar no equivale a aceptar.</div></header><main><div id="error" class="error"></div><label>Importar propuestas VLM<input id="proposals" type="file" accept="application/json"></label><label>Revisor humano<input id="reviewer"></label><button id="download" disabled>Exportar decisiones humanas</button><div id="cards"></div></main><script type="application/json" id="fixture">{data}</script><script>{JS}const fixture=JSON.parse(document.querySelector('#fixture').textContent),cards=document.querySelector('#cards'),states=new Map();cards.innerHTML=fixture.observations.map(r=>`<section class="card" data-id="${{r.observation_id}}"><h2>${{r.observation_id}}</h2><img src="${{r.reference_asset_path}}"><div class="proposal">Sin propuesta importada.</div><div class="review"><label>Estado humano<select class="status"><option value="pending">pending</option><option value="reviewed">reviewed</option><option value="corrected">corrected</option><option value="rejected">rejected</option><option value="unresolved">unresolved</option></select></label><label>Descripción revisada<textarea class="description" rows="6"></textarea></label><label>Claims revisados (JSON)<textarea class="claims" rows="10"></textarea></label><label>Incertidumbre (JSON)<textarea class="uncertainty" rows="4"></textarea></label><label>Orientación (JSON)<textarea class="orientation" rows="4"></textarea></label><label>Razón humana<textarea class="notes"></textarea></label></div></section>`).join('');
document.querySelector('#proposals').onchange=async()=>{{try{{const doc=await read(document.querySelector('#proposals'));if(doc.contract_version!=='i20-assisted-annotation-proposals-v1'||doc.plan_id!=='{plan_id}'||doc.records.length!==fixture.observations.length)throw Error('Propuestas incompatibles');const expected=fixture.observations.map(x=>x.observation_id);if(doc.records.map(x=>x.observation_id).join('|')!==expected.join('|'))throw Error('Observaciones incompatibles');for(const p of doc.records){{const card=document.querySelector(`[data-id="${{p.observation_id}}"]`),draft=clone(p.ai_draft);states.set(p.observation_id,{{proposal:p,original:clone(draft)}});card.querySelector('.proposal').textContent='PROPUESTA ORIGINAL (solo lectura)\\n'+JSON.stringify(draft,null,2);card.querySelector('.description').value=draft.description_es;card.querySelector('.claims').value=JSON.stringify(draft.claims,null,2);card.querySelector('.uncertainty').value=JSON.stringify(draft.visual_uncertainty,null,2);card.querySelector('.orientation').value=JSON.stringify(draft.orientation,null,2);card.querySelector('.status').value='pending'}}document.querySelector('#download').disabled=false}}catch(e){{showError(e)}}}};
document.querySelector('#download').onclick=()=>{{try{{const reviewer=document.querySelector('#reviewer').value.trim();if(!reviewer)throw Error('Falta revisor');const decisions=[];for(const r of fixture.observations){{const card=document.querySelector(`[data-id="${{r.observation_id}}"]`),entry=states.get(r.observation_id);if(!entry)throw Error('Falta propuesta '+r.observation_id);const status=card.querySelector('.status').value,revision={{description_es:card.querySelector('.description').value,claims:JSON.parse(card.querySelector('.claims').value),visible_text:entry.original.visible_text,visual_uncertainty:JSON.parse(card.querySelector('.uncertainty').value),orientation:JSON.parse(card.querySelector('.orientation').value),human_review_required:true}},same=JSON.stringify(revision)===JSON.stringify(entry.original),notes=card.querySelector('.notes').value.trim();if(status==='pending')throw Error('Sigue pending '+r.observation_id);if(status==='reviewed'&&!same)throw Error('reviewed contiene cambios '+r.observation_id);if(status==='corrected'&&same)throw Error('corrected sin cambios '+r.observation_id);if(['rejected','unresolved'].includes(status)&&!notes)throw Error('Falta razón '+r.observation_id);decisions.push({{decision_id:'pending-python-content-id',target_kind:'annotation',target_id:r.observation_id,proposal_id:entry.proposal.proposal_id,status,reviewer_pseudonym:reviewer,reviewed_at_utc:new Date().toISOString(),human_revision:status==='corrected'?revision:null,reason_codes:['human_'+status],notes_es:notes||null}})}}save('i20-assisted-annotation-human-decisions.draft.json',{{schema_version:'1.0',contract_version:'i20-assisted-human-decisions-v1',artifact_id:'pending-python-content-id',plan_id:'{plan_id}',decisions}})}}catch(e){{showError(e)}}}};document.documentElement.dataset.ready='true';</script></html>'''
def main():
 p=argparse.ArgumentParser();p.add_argument('--plan',type=Path,required=True);p.add_argument('--annotation-fixture',type=Path,required=True);p.add_argument('--scene-fixture',type=Path,required=True);p.add_argument('--output-root',type=Path,required=True);a=p.parse_args();plan=load(a.plan);annotation=load(a.annotation_fixture);scene=load(a.scene_fixture);a.output_root.mkdir(parents=True,exist_ok=True)
 for name,fixture,html in (('scene-review',scene,scene_html(scene,plan['plan_id'])),('annotation',annotation,annotation_html(annotation,plan['plan_id']))):
  folder=a.output_root/name;refs=folder/'references';refs.mkdir(parents=True,exist_ok=True);rows=fixture['records'] if name=='scene-review' else fixture['observations'];paths=set()
  for row in rows:
   if name=='scene-review':paths.update((row['left_reference_path'],row['right_reference_path']))
   else:paths.add(row['reference_asset_path'])
  for relative in sorted(paths):
   source=(a.scene_fixture.parent if name=='scene-review' else a.annotation_fixture.parent)/relative;destination=refs/Path(relative).name
   if not destination.exists():shutil.copyfile(source,destination)
  local=json.loads(json.dumps(fixture))
  if name=='scene-review':
   for row in local['records']:row['left_reference_path']='references/'+Path(row['left_reference_path']).name;row['right_reference_path']='references/'+Path(row['right_reference_path']).name
  else:
   for row in local['observations']:row['reference_asset_path']='references/'+Path(row['reference_asset_path']).name
   html=annotation_html(local,plan['plan_id'])
  if name=='scene-review':html=scene_html(local,plan['plan_id'])
  write(folder/'fixture.json',local);(folder/'review-assisted.html').write_text(html,encoding='utf-8');checksums(folder)
 manifest={'schema_version':'1.0','contract_version':'i20-assisted-interfaces-manifest-v1','status':'ready_no_proposals_no_human_decisions','plan_id':plan['plan_id'],'packages':{name:{'path':str(a.output_root/name),'checksums_sha256':hashlib.sha256((a.output_root/name/'CHECKSUMS.sha256').read_bytes()).hexdigest()} for name in ('scene-review','annotation')},'protocol':{'original_human_workflow_modified':False,'proposal_import_optional':True,'default_human_status':'pending','no_change_is_acceptance':False,'gt_present':False,'rankings_present':False,'osm_present':False,'holdout_present':False}};write(a.output_root/'interfaces-manifest.json',manifest);print(json.dumps({'status':manifest['status'],'scene_pairs':12,'annotations':20},sort_keys=True));return 0
if __name__=='__main__':raise SystemExit(main())
